CREATE TABLE IF NOT EXISTS agent_update_events ( event_id text PRIMARY KEY, tenant_id text NOT NULL, device_id text NOT NULL, user_id text NOT NULL DEFAULT '', current_agent_version text NOT NULL, target_agent_version text NOT NULL, release_channel text NOT NULL CHECK (release_channel IN ('lab', 'alpha', 'pilot', 'stable')), update_status text NOT NULL CHECK (update_status IN ('available', 'downloaded', 'installing', 'installed', 'failed', 'rolled_back')), update_source text NOT NULL CHECK (update_source IN ('mdm', 'control_plane', 'manual')), occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE INDEX IF NOT EXISTS agent_update_events_tenant_device_idx ON agent_update_events (tenant_id, device_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS agent_update_events_tenant_status_idx ON agent_update_events (tenant_id, update_status, occurred_at DESC);
CREATE TABLE IF NOT EXISTS agent_status_events ( agent_status_id text PRIMARY KEY, tenant_id text NOT NULL, device_id text NOT NULL, policy_bundle_id text NOT NULL, policy_bundle_version text NOT NULL, bundle_source text NOT NULL CHECK (bundle_source IN ('remote', 'cache_fallback')), device_trust_level text NOT NULL CHECK (device_trust_level IN ('managed', 'unmanaged', 'unknown')), status text NOT NULL CHECK (status IN ('healthy', 'degraded', 'offline')), occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE INDEX IF NOT EXISTS agent_status_events_tenant_device_idx ON agent_status_events (tenant_id, device_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS agent_status_events_tenant_status_idx ON agent_status_events (tenant_id, status, occurred_at DESC);
